import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String data = scanner.nextLine();
        StringBuilder answer = new StringBuilder();
        boolean replaced = false;
        int i = 0;
        while (i < data.length()) {
            if (i != 0 && i + 2 < data.length() && isDotWord(data, i)) {
                answer.append('.');
                i += 3;
                continue;
            }
            if (!replaced && i != 0 && i + 1 < data.length() && isAtWord(data, i)) {
                answer.append('@');
                i += 2;
                replaced = true;
                continue;
            }
            answer.append(data.charAt(i));
            i++;
        }
        System.out.println(answer.toString());
    }

    private static boolean isDotWord(String s, int index) {
        return s.charAt(index) == 'd' && s.charAt(index + 1) == 'o' && s.charAt(index + 2) == 't';
    }

    private static boolean isAtWord(String s, int index) {
        return s.charAt(index) == 'a' && s.charAt(index + 1) == 't';
    }
}
